\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath}
\usepackage{amssymb}
\title{Seismic Retrofit of a Soft-Storey Frame with Buckling-Restrained Braces}
\author{A. Baranov and T. Ikeda}
\date{March 2026}
\begin{document}
\maketitle

\begin{abstract}
A six-storey reinforced concrete frame with a soft ground storey is
retrofitted with buckling-restrained braces. Nonlinear time-history
analyses under seven recorded ground motions show that peak interstorey
drift falls from 2.8\% to 0.9\% after the retrofit.
\end{abstract}

\section{Structural Model}
The frame is modelled as a shear-type system. For each storey the
equation of motion under ground acceleration $\ddot{u}_g$ is
\begin{equation}
m\ddot{u} + c\dot{u} + ku = -m\ddot{u}_g,
\end{equation}
where $m$ is the storey mass, $k$ the lateral stiffness and $c$ the
damping coefficient. Throughout the paper, $c$ is chosen so that the
viscous damping ratio
\begin{equation}
\xi = \frac{c}{2\sqrt{km}}
\end{equation}
equals 0.05 for the first mode, a standard assumption for older
reinforced concrete frames.

\section{Brace Layout}
Two brace configurations are compared: a chevron layout on the ground
storey only, and a distributed layout over the lower three storeys.
The distributed layout is more effective because it reduces the drift
concentration at the soft storey without over-stiffening the base.
\end{document}
